/**
 * @name Uncontrolled data in error messages
 * @description User-controlled data flowing into error messages may expose sensitive information
 * @kind path-problem
 * @problem.severity warning
 * @id py/uncontrolled-data-in-error-message
 * @tags security
 *        external/cwe/cwe-209
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module UncontrolledDataConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call.getFunction().asExpr().(Attribute).getName() in ["set_details", "abort"] and
      sink = call.getArg(_)
    )
  }
}

module UncontrolledDataFlow = TaintTracking::Global<UncontrolledDataConfig>;
import UncontrolledDataFlow::PathGraph

from UncontrolledDataFlow::PathNode source, UncontrolledDataFlow::PathNode sink
where UncontrolledDataFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Error message contains uncontrolled data from $@.", source.getNode(), "user input"
